/**
 * @file test_h8.c
 * @brief H8 optimization polish tests (2.5.0).
 *
 * Measured gates (see docs/hpc.md 11):
 *
 *  - L-BFGS vs scipy L-BFGS-B (fixture tests/fixtures/h8_scipy_reference.txt,
 *    generated by tests/ref_h8_scipy.py with scipy 1.18.1): on rosen2/
 *    rosen10/beale/wood/matyas/exponlin10/quad50 — final f within
 *    1e-10 relative of scipy and accepted iterations within 1.25x of
 *    scipy nit (both use ftol=1e-8, gtol=1e-8, maxiter=1000*d; xtol
 *    disabled here since scipy L-BFGS-B has no xtol test).
 *  - L-BFGS box-bounded (boundquad30, box [-1,1]): final f within
 *    1e-10 relative of scipy's bounded run (iteration comparison is
 *    uninterpretable with a different line search; documented).
 *  - CD-LASSO: KKT optimality (|A_j^T r - lambda*sign(x_j)| <= 1e-8
 *    for active coords, |A_j^T r| <= lambda + 1e-8 for zeros) and
 *    objective improvement from x0=0, on a 400x80 random instance.
 *  - FISTA vs CD-LASSO on the same instance (independent algorithms):
 *    composite objectives within 1e-4 relative; both deterministic.
 *  - SPSA (2-point and 4-point) on an SPD quadratic: reaches within 5%
 *    of the full possible decrease of an L-BFGS reference; fixed-seed
 *    runs are bit-identical; 4-point does not beat 2-point at equal
 *    eval budget on this problem — the trend is REPORTED, the bar is
 *    on the decrease fraction (honest: SPSA is statistical, single
 *    seed).
 *  - Error inputs on every entry point.
 */
#include "rcre.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int g_checks = 0;
static int g_fails = 0;

#define CHECK(cond, msg)                                            \
    do {                                                            \
        ++g_checks;                                                 \
        if (!(cond)) {                                              \
            ++g_fails;                                              \
            printf("  FAIL %s:%d: %s\n", __FILE__, __LINE__, msg);  \
        }                                                           \
    } while (0)

/* ------------------------------------------------------------------ */
/* shared LCG (identical to tests/ref_h8_scipy.py and the smoke tests) */
/* ------------------------------------------------------------------ */

static double lcg01(uint64_t* st) {
    *st = *st * 6364136223846793005ull + 1442695040888963407ull;
    return (double)((*st >> 11) & ((1ull << 53) - 1)) / 9007199254740992.0;
}

/* ------------------------------------------------------------------ */
/* test functions (same definitions as the fixture script)             */
/* ------------------------------------------------------------------ */

static double tf_rosen(const double* x, void* u) {
    (void)u;
    int n = *(int*)u;
    double s = 0.0;
    for (int i = 0; i + 1 < n; ++i) {
        double a = x[i + 1] - x[i] * x[i];
        double b = 1.0 - x[i];
        s += a * a + 100.0 * b * b;
    }
    return s;
}
static void tg_rosen(const double* x, double* g, void* u) {
    (void)u;
    int n = *(int*)u;
    for (int i = 0; i < n; ++i) g[i] = 0.0;
    for (int i = 0; i + 1 < n; ++i) {
        g[i] += -2.0 * (x[i + 1] - x[i] * x[i]) - 200.0 * (1.0 - x[i]);
        g[i + 1] += 2.0 * (x[i + 1] - x[i] * x[i]);
    }
}
static double tf_beale(const double* x, void* u) {
    (void)u;
    double a = 1.5 - x[0] + x[0] * x[1];
    double b = 2.25 - x[0] + x[0] * x[1] * x[1];
    double c = 2.625 - x[0] + x[0] * x[1] * x[1] * x[1];
    return a * a + b * b + c * c;
}
static void tg_beale(const double* x, double* g, void* u) {
    (void)u;
    double a = 1.5 - x[0] + x[0] * x[1];
    double b = 2.25 - x[0] + x[0] * x[1] * x[1];
    double c = 2.625 - x[0] + x[0] * x[1] * x[1] * x[1];
    g[0] = -2 * a * (1 - x[1]) - 2 * b * (1 - x[1] * x[1])
         - 2 * c * (1 - x[1] * x[1] * x[1]);
    g[1] = 2 * a * x[0] + 4 * b * x[0] * x[1] + 6 * c * x[0] * x[1] * x[1];
}
static double tf_wood(const double* x, void* u) {
    (void)u;
    return 100 * (x[1] - x[0] * x[0]) * (x[1] - x[0] * x[0])
         + (1 - x[0]) * (1 - x[0])
         + 100 * (x[3] - x[2] * x[2]) * (x[3] - x[2] * x[2])
         + (1 - x[2]) * (1 - x[2]);
}
static void tg_wood(const double* x, double* g, void* u) {
    (void)u;
    g[0] = -400 * x[0] * (x[1] - x[0] * x[0]) - 2 * (1 - x[0]);
    g[1] = 200 * (x[1] - x[0] * x[0]);
    g[2] = -400 * x[2] * (x[3] - x[2] * x[2]) - 2 * (1 - x[2]);
    g[3] = 200 * (x[3] - x[2] * x[2]);
}
/* Styblinski-Tang: f = 1/2 sum x_i^4 - sum x_i^2 + n * sum x_i,
 * g_i = 2 x_i^3 - 2 x_i + n. Known global minimum per dim:
 * -39.165999... (n=5: f* = -195.82999...) */
static double tf_st(const double* x, void* u) {
    int n = *(int*)u;
    double s = 0.0;
    for (int i = 0; i < n; ++i)
        s += 0.5 * x[i] * x[i] * x[i] * x[i] - x[i] * x[i]
           + (double)n * x[i];
    return s;
}
static void tg_st(const double* x, double* g, void* u) {
    int n = *(int*)u;
    for (int i = 0; i < n; ++i)
        g[i] = 2.0 * x[i] * x[i] * x[i] - 2.0 * x[i] + (double)n;
}
static double tf_exponlin(const double* x, void* u) {
    (void)u;
    int n = *(int*)u;
    double s = x[n - 1] * x[n - 1];
    for (int i = 0; i + 1 < n; ++i)
        s += x[i] * x[i] - 3.7 * x[i] * x[i + 1]
           + 0.25 * x[i] * x[i] * x[i + 1] * x[i + 1];
    return s;
}
static void tg_exponlin(const double* x, double* g, void* u) {
    (void)u;
    int n = *(int*)u;
    for (int i = 0; i < n; ++i) g[i] = 0.0;
    for (int i = 0; i + 1 < n; ++i) {
        g[i] += 2.0 * x[i] - 3.7 * x[i + 1] + x[i] * x[i + 1] * x[i + 1];
        g[i + 1] += -3.7 * x[i] + 2.0 * x[i] * x[i] * x[i + 1];
    }
    g[n - 1] += 2.0 * x[n - 1];
}

/* quadratic f = 1/2 x^T Q x - p^T x (Q SPD from M^T M + d I) */
typedef struct {
    int d;
    double* Q; /* d*d row-major */
    const double* p;
} QuadT;
static double tf_quad(const double* x, void* u) {
    /* f = 1/2 x^T Q x - p^T x (NOT 1/2 x^T(Qx-p) — measured draft bug:
     * the 1/2 must apply to the quadratic term only) */
    QuadT* q = (QuadT*)u;
    int d = q->d;
    double s = 0.0, sp = 0.0;
    for (int i = 0; i < d; ++i) {
        double r = 0.0;
        for (int j = 0; j < d; ++j) r += q->Q[(size_t)i * d + j] * x[j];
        s += r * x[i];
        sp += q->p[i] * x[i];
    }
    return 0.5 * s - sp;
}
static void tg_quad(const double* x, double* g, void* u) {
    QuadT* q = (QuadT*)u;
    int d = q->d;
    for (int i = 0; i < d; ++i) {
        double r = -q->p[i];
        for (int j = 0; j < d; ++j) r += q->Q[(size_t)i * d + j] * x[j];
        g[i] = r;
    }
}

/* ------------------------------------------------------------------ */
/* fixture access                                                     */
/* ------------------------------------------------------------------ */

/*
 * Fixture row grammar (one row per line, whitespace separated):
 *   name d f nit nfev njev status x0 x1 ...       (L-BFGS results)
 *   name_data d Q00 ... Qdd p0 ... pdd x0 ... xd  (problem data)
 * scipy status: 0 = converged by ftol/gtol; 2 = the Fortran driver's
 * internal relative-step test stopped it (scipy L-BFGS-B exposes no
 * xtol; measured: exponlin10 stops at nit=1 for ANY ftol in
 * 1e-8..1e-15 — the step test is internal, not an option).
 */
static char g_fix_line[1 << 22];
static int fix_row(const char* name) {
    FILE* fp = fopen("tests/fixtures/h8_scipy_reference.txt", "r");
    if (!fp) return -1;
    int found = 0;
    while (fgets(g_fix_line, sizeof g_fix_line, fp)) {
        if (g_fix_line[0] == '#') continue;
        char nm[96] = {0};
        if (sscanf(g_fix_line, "%95s", nm) != 1) continue;
        if (strcmp(nm, name) == 0) {
            found = 1;
            break;
        }
    }
    fclose(fp);
    return found ? 0 : -1;
}

/* cursor after the "name" token */
static char* fix_skip_name(void) {
    char* c = g_fix_line;
    while (*c && *c != ' ') ++c;
    while (*c == ' ') ++c;
    return c;
}

/* returns 0 if the named row was found; fills f, nit, nfev, njev, status,
 * x[0:cap] */
static int fix_get(const char* name, double* f, int* nit, int* nfev, int* njev,
                   int* status, double* x, int cap) {
    if (fix_row(name) != 0) return -1;
    char* c = fix_skip_name();
    char* e;
    (void)strtol(c, &e, 10); /* dim */
    c = e;
    *f = strtod(c, &e);
    c = e;
    *nit = (int)strtol(c, &e, 10);
    c = e;
    *nfev = (int)strtol(c, &e, 10);
    c = e;
    *njev = (int)strtol(c, &e, 10);
    c = e;
    *status = (int)strtol(c, &e, 10);
    c = e;
    int k = 0;
    while (*c && k < cap) {
        while (*c == ' ') ++c;
        if (!*c) break;
        x[k++] = strtod(c, &e);
        c = e;
    }
    return 0;
}

/* load "name_data d Q... p... x0..." into Q (d*d), p (d), x0 (d) */
static int fix_get_data(const char* name, double* Q, double* p, double* x0,
                        int d) {
    if (fix_row(name) != 0) return -1;
    char* c = fix_skip_name();
    char* e;
    (void)strtol(c, &e, 10); /* dim */
    c = e;
    for (int k = 0; k < d * d; ++k) Q[k] = strtod(c, &e), c = e;
    for (int k = 0; k < d; ++k) p[k] = strtod(c, &e), c = e;
    for (int k = 0; k < d; ++k) x0[k] = strtod(c, &e), c = e;
    return 0;
}

/* ------------------------------------------------------------------ */
/* L-BFGS vs scipy                                                    */
/* ------------------------------------------------------------------ */

/*
 * Bars (docs/hpc.md 11):
 *  - scipy status 0 (converged by its ftol/gtol): |f_c - f_s| <= 1e-10 rel
 *    AND iters_c <= 1.25 * nit_s (+1 accepted-step off-by-one guard).
 *  - scipy status != 0 (the Fortran driver's internal relative-step test
 *    stopped it before our ftol/gtol did): f_c <= f_s (we must reach at
 *    least as low) AND iters_c <= 4 * nit_s + 2.
 */
static void lbfgs_bar(const char* name, int d, double* x0,
                      double (*f)(const double*, void*),
                      void (*g)(const double*, double*, void*), void* arg) {
    double fs, xref[64] = {0};
    int nits, nfes, njes, st;
    CHECK(fix_get(name, &fs, &nits, &nfes, &njes, &st, xref,
                  (int)(sizeof xref / 8)) == 0,
          "fixture row found");
    RCRE_LbfgsOptions o;
    rcre_lbfgs_options_default(&o);
    o.ftol = 1e-10;
    o.gtol = 1e-10;
    o.xtol = 0.0; /* scipy parity: scipy L-BFGS-B has no xtol option */
    o.max_iter = 1000 * d;
    double x[64];
    double fc;
    RCRE_OptReport rep;
    int rc = rcre_lbfgs_f64(d, f, g, arg, x0, x, &o, &fc, &rep);
    CHECK(rc == 0, "lbfgs rc");
    double scale = (fabs(fs) > 1.0) ? fabs(fs) : 1.0;
    printf("  [%s] f_c=%.9e f_s=%.9e (err %.2e) st_s=%d iters_c=%d nit_s=%d "
           "fE=%d/%d\n",
           name, fc, fs, fabs(fc - fs) / scale, st, rep.iter, nits,
           rep.f_evals, nfes);
    if (st == 0) {
        CHECK(fabs(fc - fs) <= 1e-10 * scale,
              "final-f within 1e-10 rel of scipy");
        CHECK(rep.iter <= (int)(1.25 * nits) + 1,
              "iterations within 1.25x scipy");
    } else {
        CHECK(fc <= fs + 1e-12 * scale, "early-stop class: f_c <= f_s");
        CHECK(rep.iter <= 4 * nits + 2, "early-stop class: bounded work");
    }
}

static void test_lbfgs_scipy(void) {
    printf("test_lbfgs_scipy:\n");
    int n2 = 2;
    double x0_2[2] = {-1.2, 1.0};
    lbfgs_bar("rosen2", 2, x0_2, tf_rosen, tg_rosen, &n2);

    int n10 = 10;
    double x0_10[10];
    for (int i = 0; i < 10; ++i) x0_10[i] = (i % 2 == 0) ? -1.2 : 1.0;
    lbfgs_bar("rosen10", 10, x0_10, tf_rosen, tg_rosen, &n10);

    double x0_b[2] = {1.0, 1.0};
    lbfgs_bar("beale", 2, x0_b, tf_beale, tg_beale, NULL);
    double x0_w[4] = {-1.2, 1.0, -0.2, 1.0};
    lbfgs_bar("wood", 4, x0_w, tf_wood, tg_wood, NULL);
    int n5 = 5;
    double x0_st[5];
    for (int i = 0; i < 5; ++i) x0_st[i] = 0.5;
    lbfgs_bar("styblinski5", 5, x0_st, tf_st, tg_st, &n5);

    int n10e = 10;
    double x0_e[10];
    for (int i = 0; i < 10; ++i) x0_e[i] = 0.5;
    lbfgs_bar("exponlin10", 10, x0_e, tf_exponlin, tg_exponlin, &n10e);

    /* quad50: data from the fixture */
    {
        int d = 50;
        double* Q = (double*)malloc((size_t)d * d * sizeof(double));
        double* p = (double*)malloc((size_t)d * sizeof(double));
        double* x0 = (double*)malloc((size_t)d * sizeof(double));
        CHECK(fix_get_data("quad50_data", Q, p, x0, d) == 0, "quad50 data");
        QuadT qt = {d, Q, p};
        lbfgs_bar("quad50", d, x0, tf_quad, tg_quad, &qt);
        free(Q);
        free(p);
        free(x0);
    }
    /* boundquad30: bounded — final-f bar only */
    {
        int d = 30;
        double* Q = (double*)malloc((size_t)d * d * sizeof(double));
        double* p = (double*)malloc((size_t)d * sizeof(double));
        double* x0 = (double*)malloc((size_t)d * sizeof(double));
        CHECK(fix_get_data("boundquad30_data", Q, p, x0, d) == 0,
              "boundquad30 data");
        QuadT qt = {d, Q, p};
        RCRE_LbfgsOptions o;
        rcre_lbfgs_options_default(&o);
        o.ftol = 1e-10;
        o.gtol = 1e-10;
        o.xtol = 0.0;
        o.max_iter = 1000 * d;
        o.bounded = 1;
        double lo[30], hi[30];
        for (int i = 0; i < d; ++i) {
            lo[i] = -1.0;
            hi[i] = 1.0;
        }
        o.lo = lo;
        o.hi = hi;
        double x[30];
        double f;
        RCRE_OptReport rep;
        int rc = rcre_lbfgs_f64(d, tf_quad, tg_quad, &qt, x0, x, &o, &f, &rep);
        double fs;
        int nits, nfes, njes, st;
        double xref[30] = {0};
        CHECK(
            fix_get("boundquad30", &fs, &nits, &nfes, &njes, &st, xref, 30) == 0,
            "boundquad30 row");
        CHECK(rc == 0, "lbfgs bounded rc");
        printf("  [boundquad30] f_c=%.9e f_s=%.9e (err %.2e) iters_c=%d "
               "nit_s=%d st_s=%d\n",
               f, fs,
               fabs(f - fs) / ((fabs(fs) > 1.0) ? fabs(fs) : 1.0), rep.iter,
               nits, st);
        if (st == 0) {
            CHECK(fabs(f - fs) <= 1e-10 * ((fabs(fs) > 1.0) ? fabs(fs) : 1.0),
                  "bounded final-f within 1e-10 rel");
        } else {
            CHECK(f <= fs + 1e-12, "bounded early-stop class: f_c <= f_s");
        }
        /* KKT-ish sanity: all x within the box */
        for (int i = 0; i < d; ++i)
            CHECK(x[i] >= -1.0 - 1e-12 && x[i] <= 1.0 + 1e-12, "in box");
        free(Q);
        free(p);
        free(x0);
    }
}

/* ------------------------------------------------------------------ */
/* CD-LASSO + FISTA                                                   */
/* ------------------------------------------------------------------ */

#define LASSO_N 400
#define LASSO_D 80
static double g_lasso_A[LASSO_N * LASSO_D];
static double g_lasso_b[LASSO_N];

static double tf_las_f(const double* x, void* u) {
    (void)u;
    double s = 0.0;
    for (int i = 0; i < LASSO_N; ++i) {
        double r = -g_lasso_b[i];
        for (int j = 0; j < LASSO_D; ++j)
            r += g_lasso_A[(size_t)i * LASSO_D + j] * x[j];
        s += r * r;
    }
    return 0.5 * s;
}
static void tg_las_g(const double* x, double* g, void* u) {
    (void)u;
    for (int j = 0; j < LASSO_D; ++j) g[j] = 0.0;
    for (int i = 0; i < LASSO_N; ++i) {
        double r = -g_lasso_b[i];
        for (int j = 0; j < LASSO_D; ++j)
            r += g_lasso_A[(size_t)i * LASSO_D + j] * x[j];
        for (int j = 0; j < LASSO_D; ++j)
            g[j] += g_lasso_A[(size_t)i * LASSO_D + j] * r;
    }
}
static void las_prox(const double* z, double step, double* out, void* u) {
    double lam = *(double*)u;
    for (int j = 0; j < LASSO_D; ++j) {
        double v = z[j];
        double th = step * lam;
        if (v > th) out[j] = v - th;
        else if (v < -th) out[j] = v + th;
        else out[j] = 0.0;
    }
}

static void test_lasso(void) {
    printf("test_lasso:\n");
    uint64_t st = 0x42;
    for (int i = 0; i < LASSO_N * LASSO_D; ++i)
        g_lasso_A[i] = lcg01(&st) * 2.0 - 1.0;
    for (int i = 0; i < LASSO_N; ++i) g_lasso_b[i] = lcg01(&st) * 2.0 - 1.0;

    const double lams[3] = {0.05, 0.25, 1.0};
    double zero[LASSO_D];
    for (int i = 0; i < LASSO_D; ++i) zero[i] = 0.0;

    for (int li = 0; li < 3; ++li) {
        const double lam = lams[li];
        double x_cd[LASSO_D], x_fa[LASSO_D], x_cd2[LASSO_D];
        double obj_cd, obj_cd2, f_fa;
        RCRE_OptReport rep;
        int rc = rcre_cd_lasso_f64(g_lasso_A, LASSO_N, LASSO_D, g_lasso_b, lam,
                                   zero, x_cd, 10000, 1e-10, &obj_cd, &rep);
        CHECK(rc == 0, "cd rc");
        /* determinism: second run bit-identical */
        int rc2 = rcre_cd_lasso_f64(g_lasso_A, LASSO_N, LASSO_D, g_lasso_b, lam,
                                    zero, x_cd2, 10000, 1e-10, &obj_cd2, &rep);
        CHECK(rc2 == 0 && memcmp(x_cd, x_cd2, sizeof x_cd) == 0
                  && obj_cd == obj_cd2,
              "cd deterministic");
        /* KKT: r = b - A x */
        double viol = 0.0, nnz = 0.0;
        {
            double r[LASSO_N];
            for (int i = 0; i < LASSO_N; ++i) {
                double s = g_lasso_b[i];
                for (int j = 0; j < LASSO_D; ++j)
                    s -= g_lasso_A[(size_t)i * LASSO_D + j] * x_cd[j];
                r[i] = s;
            }
            for (int j = 0; j < LASSO_D; ++j) {
                double s = 0.0;
                for (int i = 0; i < LASSO_N; ++i)
                    s += g_lasso_A[(size_t)i * LASSO_D + j] * r[i];
                /* KKT: a_j^T r = lambda*sign(x_j) for active,
                 * |a_j^T r| <= lambda for zero coordinates */
                if (x_cd[j] > 0.0) {
                    double v = fabs(s - lam);
                    if (v > viol) viol = v;
                } else if (x_cd[j] < 0.0) {
                    double v = fabs(s + lam);
                    if (v > viol) viol = v;
                } else {
                    double v = fabs(s) - lam;
                    if (v > viol) viol = v;
                }
                if (x_cd[j] != 0.0) ++nnz;
            }
        }
        /* objective improves from x0 = 0: obj(0) = 1/2||b||^2 */
        double obj0 = 0.0;
        for (int i = 0; i < LASSO_N; ++i) obj0 += g_lasso_b[i] * g_lasso_b[i];
        obj0 *= 0.5;
        printf("  [lam=%.2f] obj=%.6e nnz=%.0f kkt=%.3e iters=%d\n", lam,
               obj_cd, nnz, viol, rep.iter);
        double kkt_tol = 1e-8 * (1.0 + lam);
        CHECK(viol <= kkt_tol, "cd KKT");
        CHECK(obj_cd <= obj0, "cd improves over x0");

        /* FISTA (independent algorithm) must land on the same objective */
        double lamref = lam;
        int rc3 = rcre_fista_f64(LASSO_D, tf_las_f, tg_las_g, las_prox, &lamref,
                                 zero, x_fa, 0.0, 300000, 1e-10, &f_fa, &rep);
        CHECK(rc3 == 0, "fista rc");
        double l1fa = 0.0;
        for (int j = 0; j < LASSO_D; ++j) l1fa += fabs(x_fa[j]);
        const double obj_fa = f_fa + lam * l1fa;
        double gap = fabs(obj_fa - obj_cd) / (1.0 + fabs(obj_cd));
        printf("  [lam=%.2f] fista obj=%.6e (gap %.3e) iters=%d fE=%d\n", lam,
               obj_fa, gap, rep.iter, rep.f_evals);
        CHECK(gap <= 1e-4, "fista vs cd objective within 1e-4 rel");
        (void)obj_fa;
    }
}

/* ------------------------------------------------------------------ */
/* SPSA                                                               */
/* ------------------------------------------------------------------ */

static void test_spsa(void) {
    printf("test_spsa:\n");
    int d = 20;
    double* Q = (double*)malloc((size_t)d * d * sizeof(double));
    double* p = (double*)malloc((size_t)d * sizeof(double));
    double* x0 = (double*)malloc((size_t)d * sizeof(double));
    uint64_t st = 0x51A;
    double tmp[400];
    for (int i = 0; i < d * d; ++i) tmp[i] = lcg01(&st) * 2.0 - 1.0;
    for (int i = 0; i < d; ++i)
        for (int j = 0; j < d; ++j)
            Q[(size_t)i * d + j] = tmp[(size_t)i * d + j];
    /* Q = M^T M + d I */
    for (int i = 0; i < d; ++i)
        for (int j = 0; j < d; ++j) {
            double s = 0.0;
            for (int k = 0; k < d; ++k)
                s += tmp[(size_t)k * d + i] * tmp[(size_t)k * d + j];
            Q[(size_t)i * d + j] = s;
        }
    for (int i = 0; i < d; ++i) Q[(size_t)i * d + i] += d;
    for (int i = 0; i < d; ++i) {
        p[i] = lcg01(&st) * 2.0 - 1.0;
        x0[i] = lcg01(&st) * 2.0 - 1.0;
    }
    QuadT qt = {d, Q, p};

    /* reference: L-BFGS to convergence */
    RCRE_LbfgsOptions o;
    rcre_lbfgs_options_default(&o);
    o.ftol = 1e-12;
    o.gtol = 1e-12;
    o.xtol = 0.0;
    double xref[d];
    double fref;
    RCRE_OptReport rep;
    int rc = rcre_lbfgs_f64(d, tf_quad, tg_quad, &qt, x0, xref, &o, &fref, &rep);
    CHECK(rc == 0, "lbfgs ref rc");
    const double fstart = tf_quad(x0, &qt);
    const double need = fref + 0.05 * (fstart - fref); /* 95% of the drop */
    printf("  quad20: f_start=%.6e f_ref=%.6e need<=%.6e\n", fstart, fref, need);

    /* equal evaluation budgets: 4-point 500 steps = 1501 evals;
     * 2-point 750 steps = 1501 evals (SPSA is statistical: the bar is on
     * the reached decrease; the 4-pt vs 2-pt trend is reported).
     * a0 = 5e-3: the 4-point (sign) estimator has O(||g||^2) per-component
     * variance (measured: it explodes for a0 = 0.5 or 0.1 on this
     * problem), so the initial step must be O(1) for |g| ~ 300. */
    double x4[d], x2[d], x4b[d];
    double f4, f2, f4b;
    RCRE_OptReport r4, r2, r4b;
    rc = rcre_spsa_f64(d, tf_quad, &qt, x0, x4, 42, 0.1, 0.005, 0.6022, 500, 1,
                       &f4, &r4);
    CHECK(rc == 0, "spsa4 rc");
    rc = rcre_spsa_f64(d, tf_quad, &qt, x0, x2, 42, 0.1, 0.005, 0.6022, 750, 0,
                       &f2, &r2);
    CHECK(rc == 0, "spsa2 rc");
    /* determinism: same seed -> bit-identical */
    rc = rcre_spsa_f64(d, tf_quad, &qt, x0, x4b, 42, 0.1, 0.005, 0.6022, 500, 1,
                       &f4b, &r4b);
    CHECK(rc == 0 && memcmp(x4, x4b, sizeof x4) == 0 && f4 == f4b,
          "spsa fixed-seed deterministic");
    printf("  spsa4: f=%.6e fE=%d | spsa2: f=%.6e fE=%d (equal-budget 4-pt vs "
           "2-pt: reported)\n",
           f4, r4.f_evals, f2, r2.f_evals);
    CHECK(f4 <= need, "spsa4 reaches 95% of the drop");
    CHECK(f2 <= need, "spsa2 reaches 95% of the drop");
    free(Q);
    free(p);
    free(x0);
}

/* ------------------------------------------------------------------ */
/* error inputs                                                       */
/* ------------------------------------------------------------------ */

static void test_errors(void) {
    printf("test_errors:\n");
    RCRE_LbfgsOptions o;
    rcre_lbfgs_options_default(&o);
    double x[4] = {0}, xout[4] = {0};
    double f;
    RCRE_OptReport rep;
    int n2 = 2;
    double x0[2] = {1, 1};
    CHECK(rcre_lbfgs_f64(0, tf_rosen, tg_rosen, &n2, x0, xout, &o, &f, &rep)
              == -1,
          "lbfgs n=0");
    CHECK(rcre_lbfgs_f64(2, NULL, tg_rosen, &n2, x0, xout, &o, &f, &rep) == -1,
          "lbfgs no fun");
    o.bounded = 1;
    CHECK(rcre_lbfgs_f64(2, tf_rosen, tg_rosen, &n2, x0, xout, &o, &f, &rep)
              == -1,
          "lbfgs bounded no bounds");
    o.bounded = 0;
    CHECK(rcre_fista_f64(0, tf_rosen, tg_rosen, las_prox, &n2, x0, xout, 1.0,
                         10, 1e-8, &f, &rep)
              == -1,
          "fista n=0");
    CHECK(rcre_fista_f64(2, tf_rosen, tg_rosen, NULL, &n2, x0, xout, 1.0, 10,
                         1e-8, &f, &rep)
              == -1,
          "fista no prox");
    CHECK(rcre_fista_f64(2, tf_rosen, tg_rosen, las_prox, &n2, x0, xout, 1.0,
                         0, 1e-8, &f, &rep)
              == -1,
          "fista max_iter=0");
    CHECK(rcre_cd_lasso_f64(NULL, 10, 2, x, 1.0, x0, xout, 10, 1e-8, &f, &rep)
              == -1,
          "cd null A");
    CHECK(rcre_cd_lasso_f64(x, 10, 2, x, -1.0, x0, xout, 10, 1e-8, &f, &rep)
              == -1,
          "cd lambda<0");
    CHECK(rcre_spsa_f64(0, tf_rosen, &n2, x0, xout, 1, 0.1, 0.1, 0.6, 10, 1, &f,
                        &rep)
              == -1,
          "spsa n=0");
    CHECK(rcre_spsa_f64(2, tf_rosen, &n2, x0, xout, 1, -0.1, 0.1, 0.6, 10, 1, &f,
                        &rep)
              == -1,
          "spsa c0<0");
    CHECK(rcre_spsa_f64(2, tf_rosen, &n2, x0, xout, 1, 0.1, 0.1, 0.6, 10, 2, &f,
                        &rep)
              == -1,
          "spsa four_point=2");
    (void)x;
}

int main(void) {
    rcre_hal_init();
    test_lbfgs_scipy();
    test_lasso();
    test_spsa();
    test_errors();
    if (g_fails) {
        printf("H8: %d/%d checks FAILED\n", g_fails, g_checks);
        return 1;
    }
    printf("H8: all %d checks passed\n", g_checks);
    return 0;
}
